SourceCode.Declaration:
public class TFMReferenceDataMethodAttribute extends SysAttribute implements SysExtensionIAttribute
{
    str pagesUsingThis;
}

Method.Source:
public str parmPagesUsingThis(str _pagesUsingThis = pagesUsingThis)
{
    pagesUsingThis = _pagesUsingThis;
    return pagesUsingThis;
}

	public Set pagesUsingFilter()
    {
        Set pagesUsingFilter = new Set(Types::String);
        ListEnumerator		lEnum = strSplit(pagesUsingThis,';').getEnumerator();
        while (lEnum.moveNext() && pagesUsingThis)
        {
            pagesUsingFilter.add(lEnum.current());
        }
        return pagesUsingFilter;
    }
